"""Read-only, offline ontology browser built from a freshly computed run.

All dynamic values are text or escaped JSON. No imported HTML, scripts, network
resources, or graph URLs are executed. The browser displays captured evidence;
the Python replay command checks semantics and exact exported bytes.
"""
from __future__ import annotations

import json

from .core import canonical
from .reading_typography import font_css


def render_browser(packet: dict) -> str:
    canonical(packet)
    data = json.dumps(packet, ensure_ascii=True, separators=(",", ":"), allow_nan=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return _HTML.replace("__READING_FONT__", font_css()).replace("__ONTOLOGY_DATA__", data)


_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; font-src data:; img-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>ZAL — Find a shared structure</title>
<style>
:root{color-scheme:light;--paper:#f5f3ee;--card:#fffefa;--ink:#202e31;--muted:#53656a;--line:#c8d2cc;--accent:#17695b;--soft:#e3efe5;--warn:#825116;--warn-bg:#fff2d8;--shadow:0 10px 30px #1c443c09}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,sans-serif;line-height:1.55}button,input,select{font:inherit}button,select,input{color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:9px 12px;background:var(--card)}button{cursor:pointer}button:hover{border-color:var(--accent)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #b7682d;outline-offset:3px}button[aria-pressed=true]{background:var(--accent);color:white}a{color:var(--accent);text-underline-offset:3px}.wrap{max-width:1200px;margin:auto;padding:36px 28px 60px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:750;color:var(--accent)}h1{font-size:clamp(32px,5vw,56px);line-height:1.12;letter-spacing:-.04em;margin:15px 0}h2{font-size:23px;line-height:1.25;letter-spacing:-.025em;margin:0 0 14px}h3{font-size:17px;margin:0 0 9px}p{margin:0 0 12px}.lead{max-width:760px;font-size:18px;color:var(--muted)}.topline{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.stamp,.badge{display:inline-block;font-size:12px;border-radius:6px;background:var(--soft);color:var(--accent);padding:4px 8px;font-weight:650}.stamp{background:var(--card);border:1px solid var(--line)}.metrics{display:flex;gap:30px;margin:25px 0 30px;padding:17px 0;border-block:1px solid var(--line);flex-wrap:wrap}.metric strong{font-size:28px;margin-right:6px;letter-spacing:-.04em}.metric span{font-size:13px;color:var(--muted)}.panel{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:24px;box-shadow:var(--shadow);min-width:0}.controls{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:18px 0}label{display:grid;gap:6px;font-size:13px;font-weight:650}select{max-width:100%;width:100%;min-width:0}.examples{display:flex;gap:8px;flex-wrap:wrap}.layout{display:grid;grid-template-columns:1.04fr 1fr;gap:20px;margin-top:20px}.small{font-size:13px;color:var(--muted)}.notice{border-left:3px solid var(--accent);padding:10px 14px;background:var(--soft);font-size:14px;margin:15px 0}.warning{border-color:var(--warn);background:var(--warn-bg)}.shared{margin:15px 0;display:grid;gap:10px}.shared button{padding:14px;text-align:left;background:var(--soft);border-color:#aacbbb;display:grid;gap:4px}.shared button strong{font-size:17px;overflow-wrap:anywhere}.shared button span{font-size:12px;color:var(--muted)}.shared button[aria-pressed=true]{background:var(--accent);color:white}.shared button[aria-pressed=true] span{color:#e7f2ef}.type-list{display:flex;gap:8px;flex-wrap:wrap}.type-list button{font-size:13px;padding:6px 9px;overflow-wrap:anywhere;max-width:100%}.detail{margin-top:19px;padding-top:18px;border-top:1px solid var(--line)}.fact{overflow-wrap:anywhere}.proofs{list-style:none;padding:0;margin:16px 0;display:grid;gap:10px}.proof{border:1px solid var(--line);border-radius:10px;padding:13px 14px;background:var(--paper)}.proof .small{margin-top:5px}.proof.root{border:2px solid var(--accent);background:var(--soft)}.code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px;word-break:break-all}pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:16px;max-height:430px;overflow:auto;font-size:12px}details{margin-top:18px}summary{cursor:pointer;font-weight:650}.boundary{margin-top:22px}.boundary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.step{padding:18px;border:1px solid var(--line);border-radius:12px}.step h3{font-size:16px}.step-number{font-size:12px;letter-spacing:.1em;color:var(--muted);margin-bottom:12px}.step .badge{margin:0 0 10px}.step.fail .badge{color:var(--warn);background:var(--warn-bg)}.step p{font-size:13px}.download{display:flex;gap:17px;flex-wrap:wrap;font-size:13px;margin-top:20px}footer{margin-top:25px;font-size:12px;color:var(--muted)}#live{min-height:20px}.status-inconsistent{color:var(--warn)}.empty{padding:16px;border:1px dashed var(--line);border-radius:10px;color:var(--muted)}@media(max-width:760px){.wrap{padding:22px 16px 40px}.layout,.boundary-grid{grid-template-columns:1fr}.panel{padding:19px}.metrics{gap:16px}.controls{grid-template-columns:1fr}.lead{font-size:16px}}@media print{.wrap{max-width:none;padding:0}.examples,.controls,.download{display:none}.layout{grid-template-columns:1fr}.panel{break-inside:avoid;box-shadow:none}details[open] pre{max-height:none}.boundary-grid{grid-template-columns:1fr}.metrics{margin-bottom:16px}}
__READING_FONT__
h1,.lead,.fact,.notice,#cnl{font-family:"ZAL Reading",Georgia,serif}
h1{letter-spacing:-.025em}.lead,.fact,.notice,#cnl{font-size:18px;line-height:1.6}
#cnl{font-variant-ligatures:none}
</style></head>
<body><main class="wrap">
<div class="topline"><span class="eyebrow">ZAL / Ontology library</span><span class="stamp" id="run-status"></span></div>
<h1>Find a shared structure.</h1>
<p class="lead">Explore what two abstractions have in common. Follow each inferred category back to its stated facts and rules, then decide what stronger relationship deserves a check.</p>
<div class="metrics"><div class="metric"><strong id="individual-count"></strong><span>individuals</span></div><div class="metric"><strong id="class-count"></strong><span>classes</span></div><div class="metric"><strong id="fact-count"></strong><span>established facts</span></div><div class="metric"><strong id="inferred-count"></strong><span>derived facts</span></div></div>
<section class="panel" aria-labelledby="explore-title"><div class="topline"><h2 id="explore-title">Explore the connections</h2><div class="examples" id="examples"></div></div>
<div class="controls"><label>First abstraction<select id="left"></select></label><label>Compare with<select id="right"></select></label></div>
<p class="small" id="ontology-label"></p><p class="notice" id="assumption-note">The categories are conditional on this ontology's definitions and asserted facts. A shared category does not establish behavioral equivalence.</p>
<div id="live" class="small" role="status" aria-live="polite"></div></section>
<div class="layout"><section class="panel" aria-labelledby="shared-title"><h2 id="shared-title">Shared classes</h2><p class="small">Select a class to inspect its derivation for the first abstraction.</p><div id="shared" class="shared"></div><div class="detail"><h3 id="left-title"></h3><div id="left-types" class="type-list"></div></div><div class="detail"><h3 id="right-title"></h3><div id="right-types" class="type-list"></div></div></section>
<section class="panel" aria-labelledby="why-title"><h2 id="why-title">Why is this established?</h2><p id="selected-fact" class="fact"></p><p id="proof-note" class="small"></p><ol id="proofs" class="proofs"></ol><details><summary>Exact rule and source identities</summary><pre id="proof-json"></pre></details></section></div>
<section class="panel boundary" aria-labelledby="boundary-title"><div class="eyebrow">Three separate questions</div><h2 id="boundary-title">A category is only the beginning.</h2><p class="small">This fixed regression example uses a claim about two finite policies. Its ontology category, explicit fields, and behavioral evidence are checked separately.</p><div class="boundary-grid"><article class="step"><div class="step-number">01 / CLASSIFICATION</div><h3>Does the record fit a category?</h3><span class="badge" id="record-class"></span><p>A source property has domain ClaimRecord. This establishes a class even when the receipt is missing.</p></article><article class="step fail"><div class="step-number">02 / EXPLICIT RECORD</div><h3>Are required fields present?</h3><span class="badge" id="missing-shape"></span><p>The fixed SHACL record profile requires an explicit receipt digest. Shape validation detects the missing field.</p></article><article class="step fail"><div class="step-number">03 / EVIDENCE REPLAY</div><h3>Does the claim survive a check?</h3><span class="badge" id="forged-replay"></span><p>A forged result can have a valid digest and pass the record shape. Recomputing the finite relation still refutes it.</p></article></div><details><summary>Inspect the missing and forged evidence records</summary><pre id="boundary-json"></pre></details></section>
<section class="panel boundary"><h2>Read and reuse this ontology</h2><p class="small">Edit the controlled English or JSON, then rerun classification. The browser displays a captured run; semantic checks execute in Python.</p><details><summary>Controlled-English source</summary><pre id="cnl"></pre></details><details><summary>Scope and replay</summary><pre id="scope"></pre></details><div class="download"><a href="ontology.english.txt">Controlled English</a><a href="ontology.json">Typed ontology</a><a href="ontology.ttl">OWL / Turtle</a><a href="ontology.jsonld">JSON-LD</a><a href="classification.json">Classification and explanations</a><a href="record-shapes.ttl">Record shapes</a></div></section>
<footer>Finite positive rule profile. Missing facts remain unknown. Explanations retain one deterministic derivation. Classification grants no execution, publication, or evidence authority.</footer>
</main><script type="application/json" id="ontology-data">__ONTOLOGY_DATA__</script>
<script>
'use strict';
const packet=JSON.parse(document.getElementById('ontology-data').textContent),doc=packet.ontology,run=packet.run,result=run.result;
const byId=new Map((result.facts||[]).map(f=>[f.id,f])),proofs=new Map((result.proofs||[]).map(p=>[p.fact,p]));
const $=id=>document.getElementById(id),text=(id,value)=>{$(id).textContent=String(value)},el=(tag,value,cls)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=value;if(cls)n.className=cls;return n};
const factText=f=>f.kind==='type'?f.individual+' is a '+f.class:f.subject+' — '+f.property+' → '+f.object;
const memberships=name=>(result.facts||[]).filter(f=>f.kind==='type'&&f.individual===name).sort((a,b)=>a.class.localeCompare(b.class));
text('run-status',result.status+' · captured local run');text('individual-count',doc.individuals.length);text('class-count',doc.classes.length);text('fact-count',(result.facts||[]).length);text('inferred-count',(result.proofs||[]).filter(p=>p.premises.length>0).length);text('ontology-label',doc.id+' · revision '+doc.version);
if(result.status!=='classified'){$('assumption-note').classList.add('warning');text('assumption-note','This run is '+result.status+'. Inspect the reported limits or contradictory premises. Positive derivations are displayed diagnostically; absence never establishes a negative fact.');}
for(const side of ['left','right'])for(const name of doc.individuals){const o=el('option',name);o.value=name;$(side).append(o);}
function showProof(id){
 const target=byId.get(id);$('proofs').replaceChildren();$('proof-json').textContent='';
 if(!target){text('selected-fact','Choose an established class.');text('proof-note','An absent fact is not established; it is not automatically false.');return;}
 text('selected-fact',factText(target));text('proof-note','One deterministic premise derivation, recomputed when this packet was created.');
 const visited=new Set(),ordered=[];function visit(key){if(visited.has(key))return;visited.add(key);const p=proofs.get(key);for(const premise of p.premises)visit(premise);ordered.push(key);}visit(id);
 for(const key of ordered){const f=byId.get(key),p=proofs.get(key),li=el('li',undefined,'proof'+(key===id?' root':''));li.append(el('div',factText(f),'fact'));const support=p.premises.length?'Rule '+p.axiom+' · '+p.rule+' · '+p.premises.length+' premise(s)':'Asserted in source · '+p.assertion;li.append(el('div',support,'small'));$('proofs').append(li);}
 const axiomIds=new Set(ordered.map(k=>proofs.get(k).axiom).filter(Boolean));text('proof-json',JSON.stringify({fact:target,axioms:doc.axioms.filter(a=>axiomIds.has(a.id)),proofs:ordered.map(k=>proofs.get(k)),ontology_digest:result.ontology_digest,implementation_digest:run.implementation.digest},null,2));
 document.querySelectorAll('[data-fact]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fact===id?'true':'false'));
}
function typeButton(f){const b=el('button',f.class);b.type='button';b.dataset.fact=f.id;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>showProof(f.id));return b;}
function refresh(){const left=$('left').value,right=$('right').value,L=memberships(left),R=memberships(right),rightClasses=new Set(R.map(f=>f.class));const shared=L.filter(f=>rightClasses.has(f.class));$('shared').replaceChildren();for(const f of shared){const b=typeButton(f);b.replaceChildren(el('strong',f.class),el('span',left+' + '+right+' · shared category'));$('shared').append(b);}if(!shared.length)$('shared').append(el('p','No shared named class is established by this run.','empty'));
 for(const [side,values] of [['left',L],['right',R]]){text(side+'-title',$(side).value);$(side+'-types').replaceChildren(...values.map(typeButton));if(!values.length)$(side+'-types').append(el('p','No type established.','small'));}
 const interesting=shared.find(f=>proofs.get(f.id).premises.length>1)||shared.find(f=>proofs.get(f.id).premises.length>0)||shared[0]||L[0];showProof(interesting?interesting.id:'');text('live',shared.length+' shared classes for '+left+' and '+right+'.');}
for(const [label,a,b] of [['Training + programming','trainingRun','programmingSession'],['Alignment + requirements','alignmentReview','requirementsReview']]){if(doc.individuals.includes(a)&&doc.individuals.includes(b)){const button=el('button',label);button.type='button';button.dataset.example=a;button.addEventListener('click',()=>{$('left').value=a;$('right').value=b;refresh();});$('examples').append(button);}}
$('left').value=doc.individuals.includes('trainingRun')?'trainingRun':doc.individuals[0];$('right').value=doc.individuals.includes('programmingSession')?'programmingSession':doc.individuals[Math.min(1,doc.individuals.length-1)];$('left').addEventListener('change',refresh);$('right').addEventListener('change',refresh);refresh();
const boundary=packet.boundary;text('record-class',boundary.classification.status);text('missing-shape',boundary.missing_shape.conforms?'Conforms':'Missing receipt detected');text('forged-replay',boundary.forged_matches_replay?'Unexpected replay match':'Forged result rejected');text('boundary-json',JSON.stringify(boundary,null,2));text('cnl',packet.controlled_english);text('scope',JSON.stringify({profile:result.profile,complete:result.complete,consistency:result.consistency,limits:result.limits,usage:result.usage,source:run.implementation,ontology_digest:result.ontology_digest,replay_command:'python -m zal_notation ontology-replay --directory /path/to/export',absence:'unknown, not false',equivalence:'requires a separate scoped behavior checker',authority:'none'},null,2));
</script></body></html>
'''
